// Miles Man CRM - public Terms and Conditions e-signature.
//
// WHERE THIS GOES: copy to lib/client-agreement.js in the milesman-auth Vercel
// project (C:\Users\ericl\milesman-auth-fix), together with
//   vercel-endpoints/agreement-text.js  -> lib/agreement-text.js   (GENERATED by client-agreement/build.py)
// and add "pdf-lib" to that project's package.json dependencies, then
// `vercel --prod`. It is NOT its own function: the Vercel Hobby plan caps a
// project at 12 functions and api/ already has 12, so api/cc-auth-upload.js
// dispatches to this module when called as /api/client-agreement (a rewrite
// in vercel.json adds ?service=agreement) - same trick as /api/x-token.
// The public page that POSTs here is client-agreement-sign.html (embedded in
// the themilesman.com /client-agreement/ page).
//
// WHAT THIS DOES: receives a signature, builds the authoritative signed PDF
// SERVER-SIDE (the browser only sends the typed name, email, and a drawn
// signature image - it never supplies the agreement text, so a visitor cannot
// alter what was "signed"), saves it to the private Google Drive folder
// "Client Agreements" (a sibling of "Credit Card Authorization Forms"), emails
// eric@themilesman.com with the PDF attached, and returns the PDF to the
// browser so the client can download their own copy.
//
// WHY NO EMAIL TO THE CLIENT: this endpoint is public. Emailing whatever
// address a visitor types would let anyone make eric@themilesman.com send mail
// to a third party. The client gets their copy as an on-screen download
// instead; Eric can forward the emailed copy.
//
// AUDIT TRAIL stamped in the PDF: UTC + New York time, name, email, phone,
// agreement version, SHA-256 of the exact agreement text, IP address, and
// user-agent. This is what makes the signature attributable under the
// E-SIGN Act / UETA (intent, consent, association with the record, retention).
//
// ENV VARS (all already set for cc-auth-upload.js): GOOGLE_CLIENT_SECRET,
// DRIVE_SERVER_REFRESH_TOKEN, MS_NOTIFY_CLIENT_ID, MS_NOTIFY_CLIENT_SECRET.
// A failed notification email never fails the signing (emailSent:false is
// returned instead); a failed Drive save DOES fail it, because the stored
// record is the deliverable.
//
// SECURITY NOTE: intentionally public/unauthenticated like the other form
// endpoints. Validated input, a honeypot field, and an Origin allow-list
// only; no rate limiting - an accepted gap for a low-traffic form.

const crypto = require('crypto');
const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');
const AGREEMENT = require('./agreement-text.js');

const DRIVE_CLIENT_ID = '1055867383042-an9l58o1qg22pt7o4ak8vaneeftv54ib.apps.googleusercontent.com';
const TOKEN_URL = 'https://oauth2.googleapis.com/token';
const DRIVE_FILES_URL = 'https://www.googleapis.com/drive/v3/files';
const DRIVE_UPLOAD_URL = 'https://www.googleapis.com/upload/drive/v3/files';
const SIBLING_FOLDER_NAME = 'Credit Card Authorization Forms';
const FOLDER_NAME = 'Client Agreements';
const MAX_SIG_BYTES = 600 * 1024;

const MS_TENANT_ID = 'a9346e69-975d-4abb-861a-dea6e2464642';
const MS_TOKEN_URL = 'https://login.microsoftonline.com/' + MS_TENANT_ID + '/oauth2/v2.0/token';
const NOTIFY_EMAIL = 'eric@themilesman.com';
const MS_SEND_MAIL_URL = 'https://graph.microsoft.com/v1.0/users/' + encodeURIComponent(NOTIFY_EMAIL) + '/sendMail';

const ALLOWED_ORIGINS = ['https://milesmaneric.github.io', 'https://themilesman.com', 'https://www.themilesman.com'];

// ---------- Drive ----------
async function getServerDriveAccessToken() {
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  const refreshToken = process.env.DRIVE_SERVER_REFRESH_TOKEN;
  if (!clientSecret || !refreshToken) throw new Error('server_not_configured: Drive env vars missing.');
  const r = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: DRIVE_CLIENT_ID, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token' }).toString()
  });
  const data = await r.json();
  if (!r.ok || !data.access_token) throw new Error('drive_auth_failed: ' + (data.error_description || data.error || 'could not refresh the Drive credential'));
  return data.access_token;
}

async function driveList(accessToken, q, fields) {
  const url = DRIVE_FILES_URL + '?q=' + encodeURIComponent(q) + '&fields=' + encodeURIComponent(fields);
  const r = await fetch(url, { headers: { Authorization: 'Bearer ' + accessToken } });
  const d = await r.json();
  return r.ok && d.files ? d.files : [];
}

// Finds (or creates once) the "Client Agreements" folder next to the existing
// "Credit Card Authorization Forms" folder so it lands in the same real
// "Miles Man" folder instead of spawning a duplicate (see cc-auth-upload.js
// getUploadFolderId() for why drive.file scope makes this necessary).
async function getAgreementFolderId(accessToken) {
  const existing = await driveList(accessToken, "mimeType='application/vnd.google-apps.folder' and name='" + FOLDER_NAME + "' and trashed=false", 'files(id)');
  if (existing.length) return existing[0].id;

  let parents = ['root'];
  const sibling = await driveList(accessToken, "mimeType='application/vnd.google-apps.folder' and name='" + SIBLING_FOLDER_NAME + "' and trashed=false", 'files(id,parents)');
  if (sibling.length && sibling[0].parents && sibling[0].parents.length) parents = sibling[0].parents;

  const r = await fetch(DRIVE_FILES_URL + '?fields=id', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + accessToken, 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: FOLDER_NAME, mimeType: 'application/vnd.google-apps.folder', parents: parents })
  });
  const d = await r.json();
  if (!r.ok || !d.id) throw new Error('drive_folder_failed: ' + (d.error && d.error.message || 'could not create the "' + FOLDER_NAME + '" folder'));
  return d.id;
}

// ---------- Email (best-effort) ----------
async function getServerMsAccessToken() {
  const clientId = process.env.MS_NOTIFY_CLIENT_ID;
  const clientSecret = process.env.MS_NOTIFY_CLIENT_SECRET;
  if (!clientId || !clientSecret) throw new Error('server_not_configured: MS_NOTIFY_* env vars missing.');
  const r = await fetch(MS_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, grant_type: 'client_credentials', scope: 'https://graph.microsoft.com/.default' }).toString()
  });
  const d = await r.json();
  if (!r.ok || !d.access_token) throw new Error('ms_auth_failed: ' + (d.error_description || d.error || 'no Graph token'));
  return d.access_token;
}

async function sendSignedEmail(msToken, info, pdfBuffer) {
  const lines = [
    'The Terms and Conditions were just signed online.',
    '',
    'Name: ' + info.fullName,
    'Email: ' + info.email,
    'Phone: ' + (info.phone || '(not given)'),
    'Other travelers: ' + (info.travelers || '(none listed)'),
    'Client ID: ' + (info.clientId || '(none - signed from the general website link)'),
    'Terms version: ' + info.version,
    'Signed (New York time): ' + info.signedNy,
    'Drive link: ' + (info.webViewLink || '(unavailable)'),
    '',
    'The signed PDF is attached. To send the client their copy, forward this message to them.'
  ];
  const message = {
    subject: 'Terms and Conditions signed - ' + info.fullName,
    body: { contentType: 'Text', content: lines.join('\n') },
    toRecipients: [{ emailAddress: { address: NOTIFY_EMAIL } }],
    attachments: [{
      '@odata.type': '#microsoft.graph.fileAttachment',
      name: info.driveFilename,
      contentType: 'application/pdf',
      contentBytes: pdfBuffer.toString('base64')
    }]
  };
  const r = await fetch(MS_SEND_MAIL_URL, {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + msToken, 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: message, saveToSentItems: true })
  });
  if (!r.ok) {
    let detail = '';
    try { detail = JSON.stringify(await r.json()); } catch (e) {}
    throw new Error('graph_sendmail_failed: HTTP ' + r.status + ' ' + detail);
  }
}

// ---------- PDF ----------
// Standard PDF fonts only encode Latin-1; anything else becomes "?" so a
// client typing a name with an unusual character can never crash the signing.
function pdfSafe(s) { return String(s == null ? '' : s).replace(/[^\x20-\x7E\xA0-\xFF]/g, '?'); }

function wrapText(text, font, size, maxWidth) {
  const words = pdfSafe(text).split(/\s+/);
  const lines = [];
  let cur = '';
  for (const w of words) {
    const test = cur ? cur + ' ' + w : w;
    if (font.widthOfTextAtSize(test, size) <= maxWidth) { cur = test; }
    else { if (cur) lines.push(cur); cur = w; }
  }
  if (cur) lines.push(cur);
  return lines;
}

function agreementHash() {
  return crypto.createHash('sha256').update(JSON.stringify([AGREEMENT.VERSION, AGREEMENT.SECTIONS, AGREEMENT.ACK])).digest('hex');
}

async function buildSignedPdf(s) {
  const pdf = await PDFDocument.create();
  pdf.setTitle(AGREEMENT.TITLE + ' - ' + s.fullName);
  pdf.setAuthor('Miles Man LLC');
  pdf.setSubject('Version ' + AGREEMENT.VERSION);
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);

  const W = 612, H = 792, M = 56, CW = W - 2 * M, FS = 9.5, LH = 13;
  let page, y;
  const pages = [];
  function newPage() { page = pdf.addPage([W, H]); pages.push(page); y = H - M; }
  function ensure(h) { if (y - h < M + 14) newPage(); }
  function line(text, f, size, indent, color) {
    ensure(LH);
    page.drawText(pdfSafe(text), { x: M + (indent || 0), y: y - size, size: size, font: f, color: color || rgb(0.1, 0.1, 0.1) });
    y -= LH;
  }
  function para(text, indent, f) {
    const lines = wrapText(text, f || font, FS, CW - (indent || 0));
    for (const l of lines) line(l, f || font, FS, indent);
    y -= 4;
  }

  newPage();
  page.drawText(pdfSafe(AGREEMENT.TITLE), { x: M, y: y - 18, size: 18, font: bold, color: rgb(0.1, 0.1, 0.1) });
  y -= 28;
  para(AGREEMENT.COMPANY + '. Version ' + AGREEMENT.VERSION + '.', 0, bold);
  y -= 4;

  for (const sec of AGREEMENT.SECTIONS) {
    ensure(LH * 3);
    y -= 4;
    line(sec.heading, bold, 10.5, 0);
    y -= 2;
    for (const p of sec.paras) para(p, /^\([a-z]\) /.test(p) ? 16 : 0);
  }

  // Signature block - keep together on one page.
  ensure(300);
  y -= 8;
  page.drawLine({ start: { x: M, y: y }, end: { x: W - M, y: y }, thickness: 0.8, color: rgb(0.6, 0.6, 0.6) });
  y -= 14;
  line('SIGNED ELECTRONICALLY', bold, 11, 0);
  y -= 2;
  para(AGREEMENT.ACK, 0);

  let sigImg = null;
  try { sigImg = await pdf.embedPng(s.signatureBytes); } catch (e) { sigImg = null; }
  if (sigImg) {
    const maxW = 240, maxH = 70;
    const sc = Math.min(maxW / sigImg.width, maxH / sigImg.height);
    const w = sigImg.width * sc, h = sigImg.height * sc;
    ensure(h + 20);
    page.drawImage(sigImg, { x: M, y: y - h, width: w, height: h });
    y -= h + 4;
    page.drawLine({ start: { x: M, y: y }, end: { x: M + 260, y: y }, thickness: 0.6, color: rgb(0.3, 0.3, 0.3) });
    y -= 12;
  }
  line('Signed by: ' + s.fullName, bold, FS, 0);
  line('Email: ' + s.email + (s.phone ? '    Phone: ' + s.phone : ''), font, FS, 0);
  if (s.travelers) para('Also signing for: ' + s.travelers, 0);
  line('Date and time: ' + s.signedNy + ' (New York)  /  ' + s.signedUtc + ' (UTC)', font, FS, 0);
  y -= 6;
  line('Audit record', bold, FS, 0);
  const audit = [
    'Terms version: ' + AGREEMENT.VERSION,
    'Terms SHA-256: ' + s.hash,
    'IP address: ' + s.ip,
    'Browser: ' + s.userAgent,
    'Consent to electronic records and signature: yes (E-SIGN Act / UETA)',
    'Client ID: ' + (s.clientId || 'none (general website link)')
  ];
  for (const a of audit) {
    const lines = wrapText(a, font, 8, CW);
    for (const l of lines) line(l, font, 8, 0, rgb(0.35, 0.35, 0.35));
  }

  // Footer on every page.
  const total = pages.length;
  pages.forEach(function (p, i) {
    p.drawText(pdfSafe('Miles Man LLC - ' + AGREEMENT.TITLE + ' v' + AGREEMENT.VERSION + ' - Signed by ' + s.fullName + ' - Page ' + (i + 1) + ' of ' + total),
      { x: M, y: 28, size: 7.5, font: font, color: rgb(0.5, 0.5, 0.5) });
  });
  return Buffer.from(await pdf.save());
}

// ---------- helpers ----------
function clean(v, max) { return String(v == null ? '' : v).replace(/[\u0000-\u001F\u007F]/g, ' ').trim().slice(0, max); }
function sanitizeForFilename(str) { return (str || '').toString().trim().replace(/[^\w \-().]/g, '').slice(0, 80); }
function formatNy(d) {
  return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', dateStyle: 'long', timeStyle: 'long' }).format(d);
}

const INDEX_FILE_NAME = 'terms-signed-index.json';
function sha256Hex(v) { return crypto.createHash('sha256').update(String(v)).digest('hex'); }
function driveQuoted(v) { return String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'"); }

// Answers "has this client signed the Terms and Conditions?" for the credit card
// form, which sends the client on to sign only if the answer is no. Two sources:
//  1. the signed PDFs themselves (tagged with clientId / email in Drive), and
//  2. terms-signed-index.json, a list of hashed ids and emails the CRM writes into
//     the same folder for every client whose "Terms and Conditions signed" box is
//     ticked (this covers a box ticked by hand, e.g. for a paper signature).
// Only a yes/no goes back to the browser. Any failure answers "unknown" and the
// caller treats that as not signed, since signing twice is harmless.
async function handleStatus(b, res) {
  const clientId = clean(b.clientId, 64);
  const email = clean(b.email, 120).toLowerCase();
  if (!clientId && !email) { res.status(200).json({ ok: true, signed: false }); return; }
  try {
    const token = await getServerDriveAccessToken();
    const base = "appProperties has { key='mmType' and value='terms' } and trashed=false and ";
    if (clientId) {
      const f = await driveList(token, base + "appProperties has { key='clientId' and value='" + driveQuoted(clientId) + "' }", 'files(id)');
      if (f.length) { res.status(200).json({ ok: true, signed: true, via: 'signature' }); return; }
    }
    if (email) {
      const f = await driveList(token, base + "appProperties has { key='email' and value='" + driveQuoted(email) + "' }", 'files(id)');
      if (f.length) { res.status(200).json({ ok: true, signed: true, via: 'signature' }); return; }
    }
    const folderId = await getAgreementFolderId(token);
    const idx = await driveList(token, "name='" + INDEX_FILE_NAME + "' and '" + folderId + "' in parents and trashed=false", 'files(id)');
    if (idx.length) {
      const r = await fetch(DRIVE_FILES_URL + '/' + idx[0].id + '?alt=media', { headers: { Authorization: 'Bearer ' + token } });
      if (r.ok) {
        const data = await r.json();
        const ids = Array.isArray(data.ids) ? data.ids : [];
        const emails = Array.isArray(data.emails) ? data.emails : [];
        if ((clientId && ids.indexOf(sha256Hex(clientId)) >= 0) || (email && emails.indexOf(sha256Hex(email)) >= 0)) {
          res.status(200).json({ ok: true, signed: true, via: 'crm' }); return;
        }
      }
    }
    res.status(200).json({ ok: true, signed: false });
  } catch (e) {
    console.error('client-agreement status error:', e.message);
    res.status(200).json({ ok: true, signed: false, unknown: true });
  }
}

module.exports = async (req, res) => {
  const origin = req.headers.origin || '';
  if (ALLOWED_ORIGINS.indexOf(origin) >= 0) res.setHeader('Access-Control-Allow-Origin', origin);
  res.setHeader('Vary', 'Origin');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') { res.status(200).end(); return; }
  if (req.method !== 'POST') { res.status(405).json({ error: 'method_not_allowed' }); return; }
  if (origin && ALLOWED_ORIGINS.indexOf(origin) < 0) { res.status(403).json({ error: 'forbidden_origin' }); return; }

  const b = req.body || {};
  if (b.website) { res.status(200).json({ ok: true, honeypot: true }); return; }
  if (b.action === 'status') { await handleStatus(b, res); return; }

  const fullName = clean(b.fullName, 100);
  const email = clean(b.email, 120);
  const phone = clean(b.phone, 30);
  const travelers = clean(b.travelers, 500);
  const clientId = clean(b.clientId, 64);
  const fail = (code, msg, status) => res.status(status || 400).json({ error: code, error_description: msg });

  if (fullName.length < 3 || fullName.indexOf(' ') < 0) return fail('bad_name', 'Please type your full legal name (first and last).');
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return fail('bad_email', 'Please enter a valid email address.');
  if (b.consentAgree !== true || b.consentEsign !== true) return fail('no_consent', 'Both confirmations are required to sign.');
  if (b.version !== AGREEMENT.VERSION) return fail('version_mismatch', 'The Terms and Conditions were updated while this page was open. Please reload the page and review the latest version before signing.', 409);

  const m = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(String(b.signaturePng || ''));
  if (!m) return fail('bad_signature', 'Please draw your signature in the box.');
  const signatureBytes = Buffer.from(m[1], 'base64');
  if (!signatureBytes.length || signatureBytes.length > MAX_SIG_BYTES) return fail('bad_signature', 'The signature image was missing or too large. Please clear it and sign again.');
  if (signatureBytes.subarray(0, 4).compare(Buffer.from([0x89, 0x50, 0x4e, 0x47])) !== 0) return fail('bad_signature', 'The signature image was not valid. Please sign again.');

  const now = new Date();
  const xff = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
  const signer = {
    fullName: fullName, email: email, phone: phone, travelers: travelers, clientId: clientId,
    signatureBytes: signatureBytes,
    signedUtc: now.toISOString().replace('T', ' ').replace(/\.\d+Z$/, ' UTC').replace(' UTC', ''),
    signedNy: formatNy(now),
    ip: xff || String(req.headers['x-real-ip'] || '') || 'unknown',
    userAgent: clean(req.headers['user-agent'], 300) || 'unknown',
    hash: agreementHash()
  };

  try {
    const pdfBuffer = await buildSignedPdf(signer);
    const stamp = now.toISOString().replace(/[:.]/g, '-');
    const driveFilename = 'Terms and Conditions - ' + (sanitizeForFilename(fullName) || 'Unknown') + ' - ' + stamp + '.pdf';

    const accessToken = await getServerDriveAccessToken();
    const folderId = await getAgreementFolderId(accessToken);
    const form = new FormData();
    // appProperties tag the file so the CRM can find signed terms and tick the
    // matching client (see syncSignedTerms in index.html).
    const appProperties = { mmType: 'terms', version: AGREEMENT.VERSION, signedAt: now.toISOString() };
    if (clientId) appProperties.clientId = clean(clientId, 60);
    if (email) appProperties.email = clean(email, 80).toLowerCase();
    if (fullName) appProperties.name = clean(fullName, 70);
    form.append('metadata', new Blob([JSON.stringify({ name: driveFilename, parents: [folderId], appProperties: appProperties })], { type: 'application/json' }));
    form.append('file', new Blob([pdfBuffer], { type: 'application/pdf' }), driveFilename);
    const up = await fetch(DRIVE_UPLOAD_URL + '?uploadType=multipart&fields=id,name,webViewLink', {
      method: 'POST', headers: { Authorization: 'Bearer ' + accessToken }, body: form
    });
    const upData = await up.json();
    if (!up.ok || !upData.id) throw new Error('drive_upload_failed: ' + (upData.error && upData.error.message || 'Drive rejected the upload'));

    let emailSent = false, emailError = null;
    try {
      const msToken = await getServerMsAccessToken();
      await sendSignedEmail(msToken, {
        fullName: fullName, email: email, phone: phone, travelers: travelers, clientId: clientId,
        version: AGREEMENT.VERSION, signedNy: signer.signedNy, webViewLink: upData.webViewLink, driveFilename: driveFilename
      }, pdfBuffer);
      emailSent = true;
    } catch (emailErr) {
      console.error('client-agreement: notification email failed:', emailErr.message);
      emailError = emailErr.message;
    }

    res.status(200).json({ ok: true, fileId: upData.id, fileName: driveFilename, pdfBase64: pdfBuffer.toString('base64'), emailSent: emailSent, emailError: emailError });
  } catch (e) {
    console.error('client-agreement error:', e.message);
    res.status(500).json({ error: 'sign_error', error_description: 'We could not save your signed Terms and Conditions. Please try again, or call (908) 419-7700.' });
  }
};
